37	/// Reads `flag`'s argument (file, inline JSON, or `-` for stdin) as an unvalidated wire
38	/// value. Kept separate from the domain type's own validating constructor so a JSON parse
39	/// failure (`E281`) and a domain validation failure (its own typed `E1xx` code) are never
40	/// folded into one generic error.
41	fn read_json_arg_as<T: serde::de::DeserializeOwned>(flag: &'static str, arg: &str) -> Result<T, CliError> {
42	    let text = read_json_arg(arg)?;
43	    serde_json::from_str(&text).map_err(|error| CliError::ReleasePrArgJsonInvalid {
44	        flag,
