111	fn decide(args: ReleasePrDecideArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
112	    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_arg_as("snapshot", &args.snapshot)?;
113	    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
