27	
28	    let opts = StatusOptions { strict: args.strict };
29	
30	    let inference = crate::workspace::select_inference();
31	    let report = callisto_graph::commands::status(&ws, &inference, &opts)?;
32	
33	    match global.format {
34	        OutputFormat::Json => emit_report(&mut std::io::stdout(), &report, global.dry_run)?,
35	        OutputFormat::Text => render::render_status(&report, crate::color::enabled(), &mut crate::color::stdout())?,
36	    }
37	
38	    // `status()` already applies --strict escalation before
39	    // returning, so `has_error_diagnostics` alone reflects it.
