48	mod tests {
49	    use super::*;
50	    use callisto_model::{
51	        Ecosystem, PackageId, ReleaseTrigger, Severity, StatusPackageRecord, Version, VersionGrammar,
52	    };
53	
54	    fn v1() -> Version {
55	        Version::parse("1.0.0", VersionGrammar::SemVer).unwrap()
56	    }
57	
58	    fn pkg(name: &str) -> PackageId {
59	        PackageId::Prefixed {
60	            ecosystem: Ecosystem::Cargo,
61	            name: name.to_string(),
62	        }
63	    }
