65	    fn make_report(changesets: Vec<Vec<&str>>, diagnostics: Vec<callisto_model::Diagnostic>) -> StatusReport {
66	        let has_changesets = changesets.iter().any(|cs| !cs.is_empty());
67	        let packages: Vec<StatusPackageRecord> = changesets
68	            .into_iter()
69	            .enumerate()
70	            .map(|(i, cs)| StatusPackageRecord {
71	                package: pkg(&format!("crate-{i}")),
72	                current_version: v1(),
73	                last_tag: None,
74	                last_released_version: None,
75	                pending_severity: if cs.is_empty() { None } else { Some(Severity::Patch) },
76	                changed_since_last_tag: !cs.is_empty(),
77	                release_trigger: ReleaseTrigger::Changeset,
78	                pending_changesets: cs.into_iter().map(|s| s.to_string()).collect(),
79	            })
80	            .collect();
81	        let pending = packages.iter().filter(|p| p.pending_severity.is_some()).count() as u32;
82	        StatusReport {
83	            schema_version: callisto_model::SCHEMA_VERSION,
84	            has_changesets,
85	            pending,
86	            packages,
87	            diagnostics,
88	        }
