94	            severity: DiagnosticSeverity::Error,
95	            message: "unknown package".to_string(),
96	            package: None,
97	            path: None,
98	            governed_by: None,
99	            escalated_by: None,
100	        }
101	    }
102	
103	    // Pending changesets alone (no error-level
104	    // diagnostics) must not count as an error -- `--check` is an errors-only
105	    // gate now, unlike the pre-correction 2/3 scheme.
106	    #[test]
107	    fn has_error_diagnostics_is_false_for_pending_changesets_with_no_errors() {
108	        let report = make_report(vec![vec!["cs-001"]], vec![]);
109	        assert!(
110	            !has_error_diagnostics(&report),
111	            "pending changesets alone must not count as an error"
112	        );
113	    }
