12	/// Serializes any `Report` value to the one JSON success envelope every
13	/// command shares: `{schemaVersion, command, dryRun, ...payload,
14	/// diagnostics}`. `command` comes from `R::COMMAND`, `schemaVersion` from
15	/// the payload's own `Report::schema_version()` (re-inserted at the top
16	/// level rather than left flattened, so it appears exactly once). Callers
17	/// pass their `Report` to this function instead of hand-building a JSON envelope.
18	pub fn emit_report<W: io::Write, R: callisto_model::Report>(w: &mut W, val: &R, dry_run: bool) -> io::Result<()> {
19	    let mut value = serde_json::to_value(val)?;
20	    if let serde_json::Value::Object(map) = &mut value {
21	        map.insert("schemaVersion".to_string(), serde_json::json!(val.schema_version()));
22	        map.insert("command".to_string(), serde_json::json!(R::COMMAND));
23	        map.insert("dryRun".to_string(), serde_json::json!(dry_run));
24	    }
25	    let text = serde_json::to_string_pretty(&value)?;
26	    writeln!(w, "{text}")
27	}
28	
29	/// Writes `bytes` to stdout. A closed reading end (e.g. `callisto ... | head`)
30	/// is not a failure -- it's the normal way a consumer stops reading -- so a
31	/// `BrokenPipe` is swallowed here instead of propagating, which is what
32	/// makes this the one sink callers use in place of `println!` (which panics
33	/// on that same condition).
34	pub fn write_stdout(bytes: &[u8]) -> io::Result<()> {
35	    write_swallowing_broken_pipe(&mut io::stdout(), bytes)
36	}
37	
38	/// The actual classification [`write_stdout`] applies, pulled out so a test
39	/// can exercise it against a real closed pipe without touching the
40	/// process's real (unredirectable, in-process) stdout fd.
41	fn write_swallowing_broken_pipe<W: Write>(w: &mut W, bytes: &[u8]) -> io::Result<()> {
42	    match w.write_all(bytes) {
43	        Ok(()) => Ok(()),
44	        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => Ok(()),
45	        Err(e) => Err(e),
46	    }
47	}
48	
49	/// Writes one line (plus trailing newline) through [`write_stdout`].
50	pub fn emit_line(line: &str) -> io::Result<()> {
51	    write_stdout(format!("{line}\n").as_bytes())
52	}
53	
54	/// Writes one line to stderr -- for interactive wizard narration
55	/// (`callisto add`'s step prompts), which must stay off stdout so a script
56	/// piping stdout never sees prompt text mixed into a report or changeset preview.
57	pub fn prompt_line(line: &str) {
58	    eprintln!("{line}");
59	}
60	
61	pub fn log_line(format: OutputFormat, line: &str) -> io::Result<()> {
62	    match format {
63	        OutputFormat::Json => {
64	            eprintln!("{line}");
65	            Ok(())
66	        }
67	        OutputFormat::Text => emit_line(line),
68	    }
69	}
