236	    /// `log_line` routes purely by `OutputFormat` (Json -> stderr, Text ->
237	    /// stdout); it writes directly to the process's real fds rather than a
238	    /// caller-supplied writer, so its destination isn't capturable in-process.
239	    /// This exercises both branches to prove neither panics.
240	    #[test]
241	    fn log_line_does_not_panic_for_either_output_format() {
242	        log_line(OutputFormat::Json, "to stderr").unwrap();
243	        log_line(OutputFormat::Text, "to stdout").unwrap();
244	    }
245	}
