1	//! The one color/table decision, shared by every command's text-format output.
2	//!
3	//! `NO_COLOR` (non-empty) always wins over everything else; otherwise
4	//! `CLICOLOR_FORCE`/`FORCE_COLOR` force color on (anstream's own auto-detection
5	//! doesn't see `FORCE_COLOR`, hence checking it explicitly here); otherwise
6	//! anstream's own TTY auto-detection decides. Color and box-drawing table
7	//! formatting are never decided independently -- callers gate both off the
8	//! same [`enabled`] result.
9	
10	/// Resolves the color/table `ColorChoice` from the real process environment and stdout.
11	pub fn resolve() -> anstream::ColorChoice {
12	    resolve_with(&|name| std::env::var(name).ok())
13	}
14	
15	fn resolve_with(var: &dyn Fn(&str) -> Option<String>) -> anstream::ColorChoice {
16	    if var("NO_COLOR").is_some_and(|v| !v.is_empty()) {
17	        return anstream::ColorChoice::Never;
18	    }
19	    if var("CLICOLOR_FORCE").is_some() || var("FORCE_COLOR").is_some() {
20	        return anstream::ColorChoice::Always;
21	    }
22	    anstream::AutoStream::choice(&std::io::stdout())
23	}
24	
25	/// True when color and box-drawing table formatting should render for stdout.
26	pub fn enabled() -> bool {
27	    resolve() != anstream::ColorChoice::Never
28	}
29	
30	/// Wraps stdout in an `AutoStream` using the one resolved `ColorChoice`, so any
31	/// ANSI codes a renderer emits are stripped when color is disabled.
32	pub fn stdout() -> anstream::AutoStream<std::io::Stdout> {
33	    anstream::AutoStream::new(std::io::stdout(), resolve())
34	}
35	
36	#[cfg(test)]
37	mod tests {
38	    use super::*;
39	    use anstream::ColorChoice;
40	    use std::collections::HashMap;
41	
42	    fn vars(pairs: &[(&str, &str)]) -> HashMap<String, String> {
43	        pairs.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect()
44	    }
45	
46	    /// `NO_COLOR` set to a non-empty value always disables color, regardless of the force vars.
47	    #[test]
48	    fn no_color_non_empty_wins_over_force_vars() {
49	        let env = vars(&[("NO_COLOR", "1"), ("CLICOLOR_FORCE", "1"), ("FORCE_COLOR", "1")]);
50	        assert_eq!(resolve_with(&|k| env.get(k).cloned()), ColorChoice::Never);
51	    }
52	
53	    /// `NO_COLOR` set but empty does not disable color; `CLICOLOR_FORCE` forces it on.
54	    #[test]
55	    fn no_color_empty_does_not_suppress_clicolor_force() {
56	        let env = vars(&[("NO_COLOR", ""), ("CLICOLOR_FORCE", "1")]);
57	        assert_eq!(resolve_with(&|k| env.get(k).cloned()), ColorChoice::Always);
58	    }
59	
60	    /// `CLICOLOR_FORCE` alone forces color on.
61	    #[test]
62	    fn clicolor_force_forces_color_on() {
63	        let env = vars(&[("CLICOLOR_FORCE", "1")]);
64	        assert_eq!(resolve_with(&|k| env.get(k).cloned()), ColorChoice::Always);
65	    }
66	
67	    /// `FORCE_COLOR` alone forces color on -- anstream's own auto-detection
68	    /// doesn't see this variable, which is exactly the blind spot this module exists to close.
69	    #[test]
70	    fn force_color_forces_color_on() {
71	        let env = vars(&[("FORCE_COLOR", "1")]);
72	        assert_eq!(resolve_with(&|k| env.get(k).cloned()), ColorChoice::Always);
73	    }
74	
75	    /// Neither `NO_COLOR` nor a force var set falls back to anstream's own
76	    /// auto-detection, which always resolves to a concrete Always/Never, never Auto.
77	    #[test]
78	    fn no_env_signal_falls_back_to_concrete_auto_detection() {
79	        let env: HashMap<String, String> = HashMap::new();
80	        let choice = resolve_with(&|k| env.get(k).cloned());
81	        assert_ne!(choice, ColorChoice::Auto);
82	    }
83	
84	    /// `enabled()` mirrors `resolve()`: only `Never` disables it.
85	    #[test]
86	    fn enabled_matches_resolve_not_never() {
87	        assert_eq!(enabled(), resolve() != ColorChoice::Never);
88	    }
89	}
