1	use std::process::ExitCode;
2	
3	use callisto_graph::apply::{apply_version_plan, ApplyOptions};
4	use callisto_model::ApplyPermit;
5	
6	use crate::cli::{GlobalArgs, OutputFormat, SnapshotArgs};
7	use crate::commands::abort_on_graph_errors;
8	use crate::error::CliError;
9	use crate::output::{emit_line, emit_report};
10	use crate::render;
11	use crate::runner::CliCommandRunner;
12	use crate::workspace::load_workspace;
13	
14	pub fn handle(args: SnapshotArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
15	    let runner = CliCommandRunner;
16	    let ws = load_workspace(global, &runner)?;
17	
18	    // Promote graph diagnostics per
19	    // `--strict` and abort before touching any files.
20	    abort_on_graph_errors(ws.graph.diagnostics(), args.strict)?;
21	
22	    let (plan, report) = callisto_graph::commands::plan_snapshot(&ws, &args.tag)?;
23	
24	    // Every package converges on the same synthetic version, so each ecosystem's lockfile must
25	    // refresh too -- otherwise a stale lockfile fails `--locked` resolution right after the snapshot.
26	    let apply_opts = ApplyOptions {
27	        refresh_lockfiles: true,
28	        transient: true,
29	    };
30	
31	    if let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) {
32	        apply_version_plan(&ws.root, &plan, &runner, &apply_opts, &permit)?;
33	    }
34	
35	    match global.format {
36	        OutputFormat::Json => emit_report(&mut std::io::stdout(), &report, global.dry_run)?,
37	        OutputFormat::Text => {
38	            if global.dry_run {
39	                emit_line("[DRY-RUN] Snapshot preview (no files modified):")?;
40	            }
41	            render::render_snapshot(&report, &mut std::io::stdout())?;
42	        }
43	    }
44	
45	    Ok(ExitCode::SUCCESS)
46	}
