89	            &global,
90	        )
91	        .unwrap();
92	
93	        assert!(std::process::Command::new("git")
94	            .args(["add", "."])
95	            .current_dir(root)
96	            .status()
97	            .unwrap()
98	            .success());
99	        assert!(std::process::Command::new("git")
100	            .args(["-c", "commit.gpgSign=false", "commit", "-m", "seed", "--allow-empty"])
101	            .current_dir(root)
102	            .status()
103	            .unwrap()
104	            .success());
105	        assert!(std::process::Command::new("git")
106	            .args(["rev-parse", "--verify", "HEAD"])
107	            .current_dir(root)
108	            .status()
109	            .unwrap()
110	            .success());
111	
112	        let result = handle(
113	            SnapshotArgs {
114	                tag: "canary".to_string(),
115	                strict: false,
116	            },
117	            &global,
118	        );
119	        assert!(result.is_ok(), "expected Ok, got: {result:?}");
120	        assert_eq!(result.unwrap(), ExitCode::SUCCESS);
121	
122	        let cargo_toml = std::fs::read_to_string(pkg.join("Cargo.toml")).unwrap();
123	        assert!(
124	            cargo_toml.contains("-canary"),
125	            "a real snapshot apply must write the snapshot version to disk, got:\n{cargo_toml}"
126	        );
