13	/// Whether a status report has any error-level diagnostic. Pending state
14	/// (`report.pending`) never factors in: `--check` is a conventional
15	/// errors-only gate, and a script that wants
16	/// pending state reads `status --format json`'s `pending` count instead.
17	pub(crate) fn has_error_diagnostics(report: &StatusReport) -> bool {
18	    report
19	        .diagnostics
20	        .iter()
21	        .any(|d| d.severity == DiagnosticSeverity::Error)
22	}
23	
24	pub fn handle(args: StatusArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
25	    let runner = CliCommandRunner;
26	    let ws = load_workspace(global, &runner)?;
27	
28	    let opts = StatusOptions { strict: args.strict };
29	
30	    let inference = crate::workspace::select_inference();
31	    let report = callisto_graph::commands::status(&ws, &inference, &opts)?;
32	
33	    match global.format {
34	        OutputFormat::Json => emit_report(&mut std::io::stdout(), &report, global.dry_run)?,
35	        OutputFormat::Text => render::render_status(&report, crate::color::enabled(), &mut crate::color::stdout())?,
36	    }
37	
38	    // `status()` already applies --strict escalation before
39	    // returning, so `has_error_diagnostics` alone reflects it.
40	    if args.check && has_error_diagnostics(&report) {
41	        Ok(ExitCode::FAILURE)
42	    } else {
43	        Ok(ExitCode::SUCCESS)
44	    }
45	}
