        std::fs::create_dir_all(root.join("crates/pkg-a")).unwrap();
        std::fs::write(
            root.join("crates/pkg-a/Cargo.toml"),
            "[package]\nname = \"pkg-a\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .unwrap();

        let global = GlobalArgs {
            format: OutputFormat::Json,
