8	/// Prints the root help, or one subcommand's help when `args.command` names a
9	/// path -- clap's own `disable_help_subcommand` only removes its automatic
10	/// `help` subcommand (kept off so `--help`'s eight-command listing stays
11	/// exactly that); this hidden subcommand fills the same role explicitly.
12	pub fn handle(args: HelpArgs, _global: &GlobalArgs) -> Result<ExitCode, CliError> {
13	    let mut cmd = Cli::command();
14	    cmd.build();
15	
16	    let mut target = &mut cmd;
17	    for name in &args.command {
18	        target = target
19	            .find_subcommand_mut(name)
20	            .ok_or_else(|| CliError::HelpUnknownCommand { name: name.clone() })?;
21	    }
22	
23	    target.print_help()?;
24	    Ok(ExitCode::SUCCESS)
25	}
