17	    let existing_body = match args.existing_body {
18	        Some(ref s) if s == "-" => {
19	            let mut stdin_buf = String::new();
20	            std::io::stdin().read_to_string(&mut stdin_buf)?;
21	            let clean_stdin = stdin_buf.strip_prefix('\u{FEFF}').unwrap_or(&stdin_buf).to_string();
22	            Some(clean_stdin)
23	        }
24	        other => other,
25	    };
26	
27	    let inference = select_inference();
28	    let opts = PrBodyOptions {
29	        existing_body,
30	        branch: args.branch,
31	    };
