299	/// The workflow text and the default branch it triggers on.
300	fn build_workflow<R: CommandRunner>(
301	    facts: &InitFacts,
302	    shape: scaffold::WorkflowShape,
303	    runner: &R,
304	    human: &mut dyn Write,
305	) -> Result<(String, String), CliError> {
306	    scaffold::ensure_workflow_absent(&facts.root)?;
307	    let branch = scaffold::default_branch(runner, &facts.root);
308	    writeln!(human, "  default branch: {} (from {})", branch.name, branch.source)?;
309	    let version = env!("CARGO_PKG_VERSION");
310	    let commit = scaffold::resolve_release_commit(runner, &facts.root, version)?;
311	    let content = scaffold::render_workflow(facts, shape, &branch.name, &commit, version);
312	    Ok((content, branch.name))
313	}
