315	/// Printed, and recorded as a warning diagnostic, when no `origin` remote is configured.
316	const ORIGIN_MISSING_NOTE: &str = "No `origin` remote is configured: skipping the release workflow and \
317	shipping-binaries questions; `callisto release` will refuse until one is added.";
318	
319	/// Rejects flag combinations invalid regardless of workspace facts.
320	fn validate_flags(args: &InitArgs) -> Result<(), CliError> {
321	    if args.workflow && args.no_workflow {
322	        return Err(CliError::InitWorkflowFlagsConflict);
323	    }
324	    if args.artifact_targets.is_empty() {
325	        if args.forge_repository.is_some() {
326	            return Err(CliError::InitFlagRequiresArtifactTarget {
327	                flag: "forge-repository",
328	            });
329	        }
330	        if args.product_package.is_some() {
331	            return Err(CliError::InitFlagRequiresArtifactTarget {
332	                flag: "product-package",
333	            });
334	        }
335	    }
336	    Ok(())
337	}
