356	/// Flags `--yes` needs that were not supplied.
357	fn missing_flags(args: &InitArgs, facts: &InitFacts) -> Vec<&'static str> {
358	    let mut missing = Vec::new();
359	    if !args.artifact_targets.is_empty() && facts.binary_packages().next().is_some() {
360	        if args.forge_repository.is_none() {
361	            missing.push("--forge-repository");
362	        }
363	        if args.product_package.is_none() && facts.binary_packages().nth(1).is_some() {
364	            missing.push("--product-package");
365	        }
366	    }
367	    missing
368	}
369	
370	fn missing(flag: &'static str) -> CliError {
371	    CliError::InitMissingFlags { missing: vec![flag] }
372	}
373	
374	fn collect_answers(
375	    args: &InitArgs,
376	    facts: &InitFacts,
377	    prompting: bool,
378	    prompter: &mut dyn Prompter,
379	) -> Result<InitAnswers, CliError> {
380	    let versioning = match args.versioning {
381	        Some(InitVersioning::Fixed) => Versioning::Fixed,
382	        Some(InitVersioning::Independent) => Versioning::Independent,
383	        // Fixed and independent mean the same for one package, so only several packages are asked.
384	        None if prompting && facts.packages.len() > 1 => {
385	            let choices: Vec<String> = VERSIONING_CHOICES.iter().map(|choice| (*choice).to_owned()).collect();
386	            match prompter.select(VERSIONING_PROMPT, &choices)? {
387	                0 => Versioning::Independent,
388	                _ => Versioning::Fixed,
389	            }
390	        }
391	        None => Versioning::Independent,
392	    };
393	    let no_binaries = InitAnswers {
394	        versioning,
395	        binaries: None,
396	    };
397	
398	    let binaries: Vec<&InitPackage> = facts.binary_packages().collect();
399	    if binaries.is_empty() && !args.artifact_targets.is_empty() {
400	        if let Some(package) = facts.unsupported_artifact_packages().next() {
401	            return Err(GraphError::InitUnsupportedArtifactBuilder {
402	                package: package.id.clone(),
403	                ecosystem: package
404	                    .id
405	                    .split_once('/')
406	                    .map_or("unknown", |(ecosystem, _)| ecosystem)
407	                    .to_owned(),
408	            }
409	            .into());
410	        }
411	        return Err(GraphError::InitNoBinaryPackage.into());
412	    }
413	    let requested_product = args
414	        .product_package
415	        .as_deref()
416	        .map(|name| facts.product_package(name))
417	        .transpose()?;
418	    if binaries.is_empty() {
419	        return Ok(no_binaries);
420	    }
421	    // No `origin`: the forge question below has nothing to validate a repository against, so
422	    // shipping is never offered (skips straight to `no_binaries`); `--artifact-target` without
423	    // `origin` is already rejected up front in `run`.
424	    let ship = !args.artifact_targets.is_empty()
425	        || (facts.origin.is_some() && prompting && prompter.confirm(SHIP_PROMPT, false)?);
426	    if !ship {
427	        return Ok(no_binaries);
428	    }
429	
430	    let product = match (requested_product, binaries.as_slice()) {
431	        (Some(product), _) => product,
432	        (None, [only]) => only,
433	        (None, _) if prompting => {
434	            let ids: Vec<String> = binaries.iter().map(|package| package.id.clone()).collect();
435	            binaries[prompter.select(PRODUCT_PROMPT, &ids)?]
436	        }
437	        (None, _) => return Err(missing("--product-package")),
438	    };
439	
440	    let forge_repository = match &args.forge_repository {
441	        Some(value) => scaffold::forge_repository(facts, value)?,
442	        None if prompting => {
443	            let detected = facts.origin_repository.as_ref().map(|repository| repository.as_slug());
444	            scaffold::forge_repository(facts, &prompter.input(FORGE_PROMPT, detected.as_deref())?)?
445	        }
446	        None => return Err(missing("--forge-repository")),
447	    };
448	
449	    let targets = if args.artifact_targets.is_empty() {
450	        loop {
451	            let answer = prompter.input(TARGETS_PROMPT, None)?;
452	            let targets: Vec<String> = answer.split(',').map(str::trim).map(str::to_owned).collect();
453	            if targets.iter().all(|target| target.is_empty()) {
454	                // Nothing meaningful submitted: re-ask rather than error.
455	                continue;
456	            }
457	            break targets;
458	        }
459	    } else {
460	        args.artifact_targets.clone()
461	    };
462	    let targets = scaffold::validate_targets(&targets)?;
463	
464	    Ok(InitAnswers {
465	        versioning,
466	        binaries: Some(BinaryRelease {
467	            product: product.id.clone(),
468	            forge_repository,
469	            targets,
470	        }),
471	    })
472	}
