9	/// `cfg` is `Some` only for report kinds that can actually carry a populated
10	/// `governed_by` today (currently just `VersionReport`, via [`render_version`]);
11	/// every other caller passes `None` so this stays a no-op for them rather than
12	/// forcing every render function to thread a `ResolvedConfig` it has no
13	/// governed diagnostic to attribute.
14	pub fn render_diagnostics<W: io::Write>(
15	    diagnostics: &[callisto_model::Diagnostic],
16	    cfg: Option<&ResolvedConfig>,
17	    w: &mut W,
18	) -> io::Result<()> {
19	    if !diagnostics.is_empty() {
20	        writeln!(w, "\nDiagnostics:")?;
21	        for d in diagnostics {
22	            writeln!(w, "  [{}] {}", d.severity, d.message)?;
23	            if let (Some(cfg), Some(key)) = (cfg, d.governed_by.as_ref()) {
24	                writeln!(w, "    {}", attribution::attribution_line(key, cfg))?;
25	            }
26	        }
27	    }
28	    Ok(())
29	}
