31	/// `use_color` is the one color/table decision ([`crate::color::enabled`]):
32	/// box-drawing table formatting renders only alongside color, never independently.
33	pub fn render_status<W: io::Write>(report: &StatusReport, use_color: bool, w: &mut W) -> io::Result<()> {
34	    writeln!(w, "Status:")?;
35	    if use_color {
36	        render_status_table(report, w)?;
37	    } else {
38	        for pkg in &report.packages {
39	            writeln!(
40	                w,
41	                "  {} {} (pending: {})",
42	                pkg.package.display_name(),
43	                pkg.current_version.raw(),
44	                status_severity_label(pkg)
45	            )?;
46	        }
47	    }
48	    // `status --check`'s exit code no longer signals
49	    // pending state (0/1 gate on errors only), so the summary line and the
50	    // JSON `pending` count are how a reader sees it now.
51	    writeln!(w, "{} package(s) pending", report.pending)?;
52	    render_diagnostics(&report.diagnostics, None, w)
53	}
