61	fn render_status_table<W: io::Write>(report: &StatusReport, w: &mut W) -> io::Result<()> {
62	    use comfy_table::{presets::UTF8_FULL, Cell, Color, Table};
63	
64	    let mut table = Table::new();
65	    // Our `use_color` gate is the sole authority -- never let comfy-table's own
66	    // TTY probe override it, so a forced/piped stdout still renders styled.
67	    table.force_no_tty().enforce_styling();
68	    table.load_style(UTF8_FULL);
69	    table.set_header(vec!["Package", "Version", "Pending"]);
70	    for pkg in &report.packages {
71	        let severity = status_severity_label(pkg);
72	        let cell = match pkg.pending_severity {
73	            Some(_) => Cell::new(severity).fg(Color::Yellow),
74	            None => Cell::new(severity).fg(Color::DarkGrey),
75	        };
76	        table.add_row(vec![
77	            Cell::new(pkg.package.display_name()),
78	            Cell::new(pkg.current_version.raw()),
79	            cell,
80	        ]);
81	    }
82	    writeln!(w, "{table}")
83	}
