85	/// `cfg` is the resolved config that produced `report`: callisto prints the attribution line ("governed by ...") beneath any bump or
86	/// diagnostic whose default could defensibly have gone the other way, and
87	/// only the caller's already-resolved config has the value and provenance
88	/// that line needs (`callisto-graph` deliberately carries only the `ConfigKey`
89	/// in the report itself; see `render::attribution`).
90	pub fn render_version<W: io::Write>(report: &VersionReport, cfg: &ResolvedConfig, w: &mut W) -> io::Result<()> {
91	    writeln!(w, "Version Plan:")?;
92	    for bump in &report.bumps {
93	        writeln!(
94	            w,
95	            "  {} {} → {}",
96	            bump.package.display_name(),
97	            bump.from.raw(),
98	            bump.to.raw()
99	        )?;
100	        if let Some(key) = bump.governed_by.as_ref() {
101	            writeln!(w, "    {}", attribution::attribution_line(key, cfg))?;
102	        }
103	    }
104	    render_diagnostics(&report.diagnostics, Some(cfg), w)
105	}
