107	pub fn render_snapshot<W: io::Write>(report: &SnapshotReport, w: &mut W) -> io::Result<()> {
108	    writeln!(w, "Snapshot Tag: {}", report.snapshot_tag)?;
109	    for bump in &report.bumps {
110	        writeln!(
111	            w,
112	            "  {} {} → {}",
113	            bump.package.display_name(),
114	            bump.from.raw(),
115	            bump.to.raw()
116	        )?;
117	    }
118	    Ok(())
119	}
