126	pub fn render_init<W: io::Write>(report: &InitReport, w: &mut W) -> io::Result<()> {
127	    if report.initialized {
128	        writeln!(
129	            w,
130	            "Initialized callisto configuration at {}",
131	            report.config_path.display()
132	        )?;
133	    } else {
134	        writeln!(
135	            w,
136	            "[DRY-RUN] Would write {} (no files written)",
137	            report.config_path.display()
138	        )?;
139	    }
140	    // Every other file init wrote (or, under --dry-run, would write): the config path above
141	    // already named it, so only the rest of `files` needs listing.
142	    for file in report.files.iter().filter(|file| **file != report.config_path) {
143	        writeln!(w, "  {}", file.display())?;
144	    }
145	    render_diagnostics(&report.diagnostics, None, w)
146	}
