148	pub fn render_matrix<W: io::Write>(report: &callisto_model::MatrixReport, w: &mut W) -> io::Result<()> {
149	    writeln!(w, "Matrix:")?;
150	
151	    if report.platform_targets.is_empty() && report.runtime_versions.is_empty() {
152	        writeln!(w, "  (no platform targets or runtime-version constraints declared)")?;
153	    }
154	
155	    for (pkg, group) in &report.platform_targets {
156	        writeln!(w, "  {pkg} [{} <- {}]:", group.kind, group.source)?;
157	        for t in &group.targets {
158	            writeln!(
159	                w,
160	                "    {:<32} abi={:<8} runner={:<14} cross={:<5} artifact={}",
161	                t.triple,
162	                t.abi.as_deref().unwrap_or("-"),
163	                t.host_runner,
164	                t.use_cross,
165	                t.artifact_name
166	            )?;
167	        }
168	    }
169	
170	    for (pkg, entries) in &report.runtime_versions {
171	        for e in entries {
172	            writeln!(w, "  {pkg} [{}] {} = {}", e.ecosystem, e.field, e.range)?;
173	        }
174	    }
175	
176	    render_diagnostics(&report.diagnostics, None, w)
177	}
