212	    fn render_status_no_some_wrapper_in_output() {
213	        let report = StatusReport {
214	            schema_version: callisto_model::SCHEMA_VERSION,
215	            has_changesets: true,
216	            pending: 1,
217	            packages: vec![status_pkg("crate-a", Some(Severity::Minor), vec!["cs-001"])],
218	            diagnostics: vec![],
219	        };
220	        let mut out = Vec::new();
221	        render_status(&report, false, &mut out).unwrap();
222	        let text = String::from_utf8(out).unwrap();
223	        assert!(
224	            !text.contains("Some("),
225	            "render_status output must not contain 'Some('; got: {text}"
226	        );
227	        assert!(
228	            text.contains("minor"),
229	            "render_status output should contain severity 'minor'; got: {text}"
230	        );
231	    }
