233	    /// `render_diagnostics` prints each diagnostic's severity with its
234	    /// `Display` impl (lowercase, e.g. `warning`), not `{:?}`'s PascalCase
235	    /// Rust variant name.
236	    #[test]
237	    fn render_diagnostics_prints_lowercase_severity() {
238	        use callisto_model::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
239	
240	        let diagnostics = vec![Diagnostic {
241	            code: DiagnosticCode::EmptyChangeset,
242	            severity: DiagnosticSeverity::Warning,
243	            message: "no pending changesets".to_string(),
244	            package: None,
245	            path: None,
