18	fn stage_pre_json(runner: &dyn CommandRunner, root: &Path, rel_path: &Path) -> Result<(), CliError> {
19	    let rel_str = rel_path.to_string_lossy();
20	    let output = runner.run("git", &["add", rel_str.as_ref()], root)?;
