32	/// A baseline that fits no version grammar is a malformed owned baseline (E114), as in `version`; other damage is E212.
33	fn parse_existing_pre_json(text: &str) -> Result<PreState, CliError> {
34	    parse_pre_json(text).map_err(|error| match error {
35	        PreJsonError::InvalidInitialVersion { .. } => CliError::Graph(GraphError::PreJson(error)),
36	        other => CliError::PreJson(other),
37	    })
