40	/// Mirrors `add`'s dry-run preview so both commands report the not-yet-written content the same way.
41	fn preview(global: &GlobalArgs, mode: &str, tag: &str, rel_path: &Path, content: &str) -> Result<(), CliError> {
42	    let rel_str = rel_path.to_string_lossy();
43	    match global.format {
44	        OutputFormat::Json => {
45	            let report = PreReport {
46	                schema_version: SCHEMA_VERSION,
47	                mode: mode.to_string(),
48	                tag: tag.to_string(),
49	                path: Some(rel_str.into_owned()),
50	                content: Some(content.to_string()),
51	                diagnostics: vec![],
52	            };
53	            emit_report(&mut std::io::stdout(), &report, true)?;
54	        }
55	        OutputFormat::Text => {
56	            emit_line(&format!(
57	                "[DRY-RUN] Would write {rel_str} (no files written)\n\n{content}"
58	            ))?;
59	        }
60	    }
61	    Ok(())
62	}
