4	pub fn attribution_line(key: &ConfigKey, cfg: &ResolvedConfig) -> String {
5	    let key_str = key.as_str();
6	    let formatted_key = if let Some((table, field)) = key_str.split_once('.') {
7	        format!("[{table}].{field}")
8	    } else {
9	        key_str.to_string()
10	    };
11	
12	    let prov = cfg.provenance(key);
13	    // release-trigger is package-scoped and has no rendered value here; its real default is `changeset`, not "auto".
14	    let val = cfg.rendered_value(key).unwrap_or_else(|| {
15	        if key == &ConfigKey::RELEASE_TRIGGER {
16	            match ReleaseTrigger::default() {
17	                ReleaseTrigger::Changeset => "changeset".to_string(),
18	                ReleaseTrigger::Auto => "auto".to_string(),
19	            }
20	        } else {
21	            "auto".to_string()
22	        }
23	    });
24	
25	    match prov {
26	        ConfigProvenance::Default => format!("governed by {formatted_key} = {val} (default)"),
27	        ConfigProvenance::Explicit => format!("governed by {formatted_key} = {val}"),
28	    }
29	}
