64	/// Handles the `pre enter` and `pre exit` subcommands.
65	///
66	/// `pre enter` writes `.changeset/pre.json` with the supplied tag and a snapshot
67	/// of current package versions. `pre exit` updates an existing `pre.json`'s mode
68	/// to `exit`. Under `--dry-run`, neither subcommand writes any file; instead the
69	/// would-be content is rendered to stdout.
70	///
71	/// # Errors
72	///
73	/// Returns [`CliError::PreAlreadyActive`] if `enter` runs while `pre.json`'s mode
74	/// is already `pre`, and [`CliError::PreNotActive`] if `exit` runs with no
75	/// `pre.json` on disk. Otherwise returns [`CliError::Io`] if reading an existing
76	/// `pre.json` fails, or if any write fails (`enter` subcommand on a real run).
77	pub fn handle(args: PreArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
78	    let runner = CliCommandRunner;
79	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run);
80	
81	    match args {
82	        PreArgs::Enter { tag } => {
83	            // Bug 3: reject empty tags before any workspace I/O.
84	            if tag.trim().is_empty() {
85	                return Err(CliError::PreTagEmpty);
86	            }
87	
88	            let ws = load_workspace(global, &runner)?;
89	
90	            // Reject re-entering only while a cycle is actually active (mode `pre`); a `pre.json` left
91	            // behind in `exit` mode is a finished cycle, so entering starts a new one from where it
92	            // left off instead of erroring on a file that merely still exists on disk.
93	            let rel_pre_path = ws.config.pre_json_path();
94	            let pre_path = ws.root.join(&rel_pre_path);
95	            let pre_dir = pre_path.parent().unwrap_or(&ws.root).to_path_buf();
96	            let existing_text = callisto_model::strict_fs::read_optional(&pre_path).map_err(|source| CliError::Io {
97	                source,
98	                path: Some(pre_path.clone()),
99	            })?;
100	            let pre_state = if let Some(existing_text) = existing_text {
101	                let existing = parse_existing_pre_json(&existing_text)?;
102	                if existing.mode == PreMode::Pre {
103	                    return Err(CliError::PreAlreadyActive);
104	                }
105	                let existing = ws.resolve_pre_state_from_json(existing, &existing_text)?;
106	                // Re-entering after `exit` carries the same initial-versions baseline and recorded
107	                // changesets forward under the new tag, matching a resumed rather than a fresh cycle.
108	                PreState {
109	                    mode: PreMode::Pre,
110	                    tag: tag.clone(),
111	                    ..existing
112	                }
113	            } else {
114	                let initial = ws.initial_versions()?;
115	                let mut snapshot = indexmap::IndexMap::new();
116	                for (k, v) in initial {
117	                    snapshot.insert(k, v);
118	                }
119	                PreState::entering(tag.clone(), snapshot)
120	            };
121	            let text = write_pre_json(&pre_state);
122	
123	            let Some(permit) = permit else {
124	                preview(global, "pre", &tag, &rel_pre_path, &text)?;
125	                return Ok(ExitCode::SUCCESS);
126	            };
127	
128	            fs::create_dir_all(&pre_dir)?;
129	            callisto_manifests::atomic::atomic_write(&pre_path, &text, &permit)?;
130	
131	            // Bug 4: stage pre.json so it is included in the next commit.
132	            stage_pre_json(&runner, &ws.root, &rel_pre_path)?;
133	
134	            match global.format {
135	                OutputFormat::Json => {
136	                    let report = PreReport {
137	                        schema_version: SCHEMA_VERSION,
138	                        mode: "pre".to_string(),
139	                        tag: tag.clone(),
140	                        path: None,
141	                        content: None,
142	                        diagnostics: vec![],
143	                    };
144	                    emit_report(&mut std::io::stdout(), &report, false)?;
145	                }
146	                OutputFormat::Text => {
147	                    log_line(global.format, &format!("Entered pre mode with tag `{tag}`"))?;
148	                }
149	            }
150	        }
151	        PreArgs::Exit => {
152	            let start = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
153	                source,
154	                path: Some(global.cwd.clone()),
155	            })?;
156	            let root = callisto_graph::locate::find_workspace_root(&start, &runner)?;
157	            let config = callisto_graph::load_config(&root)?;
158	            let rel_pre_path = config.pre_json_path();
159	            let pre_path = root.join(&rel_pre_path);
160	
161	            let text = callisto_model::strict_fs::read_optional(&pre_path)
162	                .map_err(|source| CliError::Io {
163	                    source,
164	                    path: Some(pre_path.clone()),
165	                })?
166	                .ok_or(CliError::PreNotActive)?;
167	            let mut pre_state = parse_existing_pre_json(&text)?;
168	
169	            // Reject double-exit.
170	            if pre_state.mode == PreMode::Exit {

168	
169	            // Reject double-exit.
170	            if pre_state.mode == PreMode::Exit {
171	                return Err(CliError::PreAlreadyExited);
172	            }
173	
174	            let ws = load_workspace(global, &runner)?;
175	            pre_state = ws.resolve_pre_state_from_json(pre_state, &text)?;
176	            pre_state.mode = PreMode::Exit;
177	
178	            let updated = write_pre_json_preserving(&pre_state, &text);
179	
180	            let Some(permit) = permit else {
181	                preview(global, "exit", &pre_state.tag, &rel_pre_path, &updated)?;
182	                return Ok(ExitCode::SUCCESS);
183	            };
184	
185	            callisto_manifests::atomic::atomic_write(&pre_path, &updated, &permit)?;
186	
187	            // Mutates the same tracked file `pre enter` created, so it must be staged the same way.
188	            stage_pre_json(&runner, &root, &rel_pre_path)?;
189	
190	            match global.format {
191	                OutputFormat::Json => {
192	                    let report = PreReport {
193	                        schema_version: SCHEMA_VERSION,
194	                        mode: "exit".to_string(),
195	                        tag: pre_state.tag.clone(),
196	                        path: None,
197	                        content: None,
198	                        diagnostics: vec![],
199	                    };
200	                    emit_report(&mut std::io::stdout(), &report, false)?;
201	                }
202	                OutputFormat::Text => {
203	                    log_line(global.format, "Exiting pre mode")?;
204	                }
205	            }
206	        }
207	    }
208	
209	    Ok(ExitCode::SUCCESS)
210	}
